<script setup>
import {ref,onMounted,watch} from 'vue';import {useRouter} from 'vue-router';import {api,mutate,notify,ui} from '../lib/api.js';import {money,dateLabel,today,downloadCsv} from '../lib/format.js';import PageTitle from '../components/PageTitle.vue';import Icon from '../components/Icon.vue';import Badge from '../components/Badge.vue';import RevenueChart from '../components/RevenueChart.vue';import CrudForm from '../components/CrudForm.vue';import EmptyState from '../components/EmptyState.vue';
const router=useRouter(),data=ref(null),subscriptions=ref([]),payments=ref({rows:[],count:0}),period=ref('year'),from=ref(today().slice(0,4)+'-01-01'),to=ref(today()),error=ref(''),open=ref(false),paymentOpen=ref(false),page=ref(1);
async function load(){try{error.value='';[data.value,subscriptions.value,payments.value]=await Promise.all([api(`/dashboard?period=${period.value}&from=${from.value}&to=${to.value}`),api('/subscriptions'),api(`/payments?page=${page.value}&limit=25`)]);}catch(e){error.value=e.message;}}
onMounted(load);watch([period,from,to,page,()=>ui.revision],load);
async function toggle(s){try{await mutate('/subscriptions/'+s.id,'PATCH',{active:!s.active},s.active?'Abonnement arrêté.':'Abonnement réactivé.');}catch(e){notify(e.message,'error');}}
function exportReport(){downloadCsv('birostweb-finances.csv',['Période','Encaissements TTC EUR','Dépenses payées TTC EUR','Solde EUR'],data.value.chart.map(r=>[r.key,(r.revenue/100).toFixed(2),(r.expenses/100).toFixed(2),((r.revenue-r.expenses)/100).toFixed(2)]));}
async function bill(s){try{const i=await mutate('/subscriptions/'+s.id+'/invoice','POST',{nextDate:s.nextDate},'Brouillon créé ; échéance avancée.');router.push('/invoices/'+i.id);}catch(e){notify(e.message,'error');}}
</script>
<template><PageTitle number="10" title="LES FINANCES" subtitle="Comprendre les chiffres. Préparer la suite."><button class="btn" @click="exportReport" :disabled="!data"><Icon name="Download"/>Exporter</button><button class="btn primary" @click="paymentOpen=true"><Icon name="Plus"/>Enregistrer un paiement</button></PageTitle><div class="toolbar"><div class="segmented"><button v-for="[v,l] in [['7d','7 JOURS'],['30d','30 JOURS'],['3m','3 MOIS'],['year','ANNÉE'],['custom','PERSONNALISÉ']]" :key="v" :class="{selected:period===v}" @click="period=v">{{l}}</button></div><div class="custom-dates" v-if="period==='custom'"><label>Du<input v-model="from" type="date"></label><label>Au<input v-model="to" type="date"></label></div></div><p v-if="error" class="form-error">{{error}}</p><template v-if="data"><div class="metrics-strip"><div><small>ENCAISSÉ SUR LA PÉRIODE TTC</small><strong>{{money(data.stats.collected)}}</strong></div><div><small>DÉPENSES DE LA PÉRIODE TTC</small><strong>{{money(data.stats.expenses)}}</strong></div><div><small>SOLDE DE TRÉSORERIE ESTIMÉ</small><strong class="accent">{{money(data.stats.cashMargin)}}</strong></div></div><section class="panel"><div class="panel-head"><div><span class="eyebrow">LA TRAJECTOIRE DU STUDIO</span><h2>REVENUS & DÉPENSES.</h2></div><span class="eyebrow muted">{{data.from}} → {{data.to}}</span></div><RevenueChart :rows="data.chart"/><div class="chart-legend"><span><i class="legend-accent"></i>Encaissements TTC</span><span><i class="legend-muted"></i>Dépenses payées TTC</span></div></section><div class="finance-grid"><section class="panel" v-for="[key,title] in [['serviceCategories','REVENUS PAR PRESTATION.'],['expenseCategories','DÉPENSES PAR CATÉGORIE.']]" :key="key"><div class="panel-head"><h2>{{title}}</h2></div><div class="breakdown"><div v-for="[label,value] in Object.entries(data[key]).sort((a,b)=>b[1]-a[1])" :key="label" class="breakdown-row"><div class="row-between"><span>{{label}}</span><strong>{{money(value,true)}}</strong></div><div class="progress-track" :class="{'muted-bar':key==='expenseCategories'}"><i :style="{width:(value/Math.max(1,...Object.values(data[key]))*100)+'%'}"></i></div></div><p class="field-note">{{key==='serviceCategories'?'Encaissements affectés aux prestations, hors TVA.':'Montants TTC des factures fournisseurs sur la période.'}}</p></div></section></div><div class="metrics-strip"><div><small>DEVIS ACCEPTÉS / ENVOYÉS</small><strong>{{data.stats.quotesAccepted}} / {{data.stats.quotesSent}} <span style="font-size:20px" class="muted">{{data.stats.conversion}}%</span></strong></div><div><small>PANIER MOYEN DES PROJETS TTC</small><strong>{{money(data.stats.averageOrder)}}</strong></div><div><small>NOUVEAUX CLIENTS SUR LA PÉRIODE</small><strong>{{String(data.stats.newClients).padStart(2,'0')}}</strong></div></div><section class="panel"><div class="panel-head"><div><span class="eyebrow">L’ACTIVITÉ QUI DURE</span><h2>LES ABONNEMENTS.</h2></div><button class="btn" @click="open=true"><Icon name="Plus"/>Ajouter</button></div><div class="metrics-strip" style="border-left:0;border-right:0;margin-bottom:0"><div><small>MRR HT</small><strong class="accent">{{money(data.stats.mrr,true)}} <span style="font-size:16px">/ mois</span></strong></div><div><small>ARR ESTIMÉ HT</small><strong>{{money(data.stats.arr,true)}}</strong></div><div><small>ABONNEMENTS ACTIFS</small><strong>{{subscriptions.filter(s=>s.active).length}}</strong></div></div><div class="table-scroll"><table><thead><tr><th>CLIENT / PRESTATION</th><th>MONTANT HT</th><th>FRÉQUENCE</th><th>PROCHAINE ÉCHÉANCE</th><th>STATUT</th><th></th></tr></thead><tbody><tr v-for="s in subscriptions" :key="s.id"><td><RouterLink class="table-title" :to="'/clients/'+s.clientId">{{s.client.name}}</RouterLink><div class="table-sub">{{s.name}}</div></td><td>{{money(s.amountCents,true)}}</td><td>{{s.frequency==='monthly'?'Mensuelle':'Annuelle'}}</td><td>{{dateLabel(s.nextDate,true)}}</td><td><Badge :status="s.active?'active':'archived'"/></td><td><button v-if="s.active" class="text-button" @click="bill(s)" style="margin-right:14px">Facturer<Icon name="ArrowUpRight" :size="14"/></button><button class="text-button" @click="toggle(s)">{{s.active?'Arrêter':'Réactiver'}}</button></td></tr></tbody></table></div><EmptyState v-if="!subscriptions.length" title="Un revenu qui se construit." description="Ajoutez vos contrats d’hébergement et de maintenance."/></section><section class="panel" style="margin-top:24px"><div class="panel-head"><h2>LE JOURNAL DES ENCAISSEMENTS.</h2></div><div class="table-scroll"><table><thead><tr><th>DATE</th><th>CLIENT</th><th>FACTURE / PROJET</th><th>MONTANT TTC</th><th>RÉFÉRENCE</th></tr></thead><tbody><tr v-for="p in payments.rows" :key="p.id"><td>{{dateLabel(p.date,true)}}</td><td>{{p.client.name}}</td><td><RouterLink v-if="p.invoice" :to="'/invoices/'+p.invoiceId">{{p.invoice.reference}}</RouterLink><RouterLink v-else-if="p.project" :to="'/projects/'+p.projectId">{{p.project.reference}}</RouterLink></td><td class="mono">{{money(p.amountCents,true)}}</td><td>{{p.reference||'—'}}</td></tr></tbody></table></div><footer class="pagination"><span>{{payments.count}} paiements</span><div><button class="icon-button" :disabled="page===1" @click="page--" aria-label="Page précédente"><Icon name="ChevronLeft"/></button><span>{{page}}</span><button class="icon-button" :disabled="page*25>=payments.count" @click="page++" aria-label="Page suivante"><Icon name="ChevronRight"/></button></div></footer></section><p class="field-note" style="margin-top:18px">Le solde présenté compare les encaissements aux dépenses payées. Il ne déduit pas vos cotisations, impôts ou amortissements.</p></template><CrudForm :open="open" kind="subscriptions" @close="open=false"/><CrudForm :open="paymentOpen" kind="payments" @close="paymentOpen=false"/></template>
